function recolArt(c,t){try{const g=c.getContext('2d'),d=g.getImageData(0,0,c.width,c.height),a=d.data;for(let i=0;i<a.length;i+=4){const r=a[i]/255,gg=a[i+1]/255,b=a[i+2]/255,L=.3*r+.59*gg+.11*b,mx=Math.max(r,gg,b),mn=Math.min(r,gg,b),sat=mx?(mx-mn)/mx:0;
 if(t=='X'){if(L>.3&&b>=r-.02){const k=Math.min(1,(L-.3)/.2);const R2=Math.min(1,L*1.22+.06),G2=Math.min(1,L*1.02),B2=L*.42;a[i]=255*(r+(R2-r)*k);a[i+1]=255*(gg+(G2-gg)*k);a[i+2]=255*(b+(B2-b)*k)}}
 else{if(b>r&&sat>.08){const k=.6;a[i]=255*(r+(L*1.05-r)*k);a[i+1]=255*(gg+(L*1.05-gg)*k);a[i+2]=255*(b+(L*1.1-b)*k)}}}g.putImageData(d,0,0)}catch(_){}}
