  for(const[a0,b0,a1,b1]of[[x-r,y-r,x,y],[x,y-r,x+r,y],[x-r,y,x,y+r],[x,y,x+r,y+r]]){const x0=Math.max(0,a0),y0=Math.max(0,b0),x1=Math.min(W-1,a1),y1=Math.min(H-1,b1),m=(x1-x0+1)*(y1-y0+1),mu=box(L,x0,y0,x1,y1)/m,v=box(L2,x0,y0,x1,y1)/m-mu*mu;if(v<best){best=v;B=[x0,y0,x1,y1,m]}}
