function canPlay(o,Q){const i=G.P.indexOf(Q);return !(o.t=='B'&&!Q.gy.length)&&!(o.t=='M'&&!G.P.some((P,j)=>j!=i&&P.bf.length))&&!(o.t=='Q'&&G.P.filter((P,j)=>j!=i&&P.bf.length).length<2)}
function cantPlay(o){if(o.t=='M'){fl(o.mesh.position,tr('El rival no tiene cartas'),'#d8502a');msg('No puedes jugar Fuego si el rival no tiene cartas en el campo')}else{fl(o.mesh.position,tr('Tu cementerio está vacío'),'#8a5ab8');msg('No puedes jugar Tierra si no tienes cartas en tu cementerio')}}
function winsWith(bf,t){const L=t=='X'?[...'PBMSI'].map(c=>({t:'X',ct:c})):[{t}];return L.some(f=>!!wcB(bf.concat([f])))}
function pureWith(bf,t){if(t=='X')return false;const r=wcB(bf.concat([{t}]));return !!(r&&r.pure)}
function knownHand(O){return O===G.P[0]?O.hand.filter(x=>x.kn):O.hand.filter(x=>x.pub||x.rv)}
function threatOf(O){const nx=[...'PBMSIX'].filter(t=>winsWith(O.bf,t)),kh=knownHand(O).filter(x=>winsWith(O.bf,x.t));return{nx,kh,danger:nx.length>0,sure:kh.length>0,decl:!!(G.decl&&G.decl.s===G.P.indexOf(O)&&wcB(O.bf))}}
