function tr(s){if(LANG=='es'||s==null)return s;s=String(s);const k={en:1,zh:2,pt:3,ja:4,fr:5}[LANG];if(GTIT.test(s)){const m=s.match(GTIT)[0];return s.split(m).map(p=>p.replace(I18RE,x=>I18M[x][k])).join(m)}return s.replace(I18RE,m=>I18M[m][k])}
