function trNode(n){const cur=n.nodeValue;if(!cur||!cur.trim())return;const pe=n.parentNode;if(pe&&pe.classList&&(pe.classList.contains('lw')||pe.classList.contains('lwd')))return;let o=TRO.get(n);if(!o||o.out!==cur)o={src:cur};let out=tr(o.src);if(ING&&n.parentNode&&n.parentNode.closest&&n.parentNode.closest('#m,#md,#tk,#hl,#bo3,#hist,#ov'))out=rivN(out);o.out=out;TRO.set(n,o);if(out!==cur)n.nodeValue=out}
