function sTone(t,type,f0,f1,dur,pk,att,lp){const o=AC.createOscillator(),g=AC.createGain();o.type=type;o.frequency.setValueAtTime(f0,t);if(f1!=f0)o.frequency.exponentialRampToValueAtTime(f1,t+dur*.8);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(pk,t+(att||.005));g.gain.exponentialRampToValueAtTime(.0001,t+dur);if(lp){const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(lp,t);f.frequency.exponentialRampToValueAtTime(lp*.35,t+dur);o.connect(f);f.connect(g)}else o.connect(g);g.connect(FX);o.start(t);o.stop(t+dur+.05)}
function sFlutter(D){if(!acInit())return;D=D||2;const t=AC.currentTime+.05,n=AC.createBufferSource(),f=AC.createBiquadFilter(),am=AC.createGain(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();n.buffer=noiseBuf(D+.1);f.type='bandpass';f.Q.value=.9;f.frequency.setValueAtTime(1500,t);f.frequency.linearRampToValueAtTime(2300,t+D*.5);f.frequency.linearRampToValueAtTime(1700,t+D);l.type='triangle';l.frequency.setValueAtTime(9,t);l.frequency.linearRampToValueAtTime(13,t+D*.5);l.frequency.linearRampToValueAtTime(8,t+D);am.gain.value=.5;lg.gain.value=.5;l.connect(lg);lg.connect(am.gain);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.085,t+.35);g.gain.setValueAtTime(.085,t+D-.7);g.gain.exponentialRampToValueAtTime(.0001,t+D);n.connect(f);f.connect(am);am.connect(g);g.connect(FX);n.start(t);n.stop(t+D+.05);l.start(t);l.stop(t+D+.05)}
function sWave(){if(!acInit())return;const t=AC.currentTime;sNz(t,.6,'lowpass',260,1700,380,.7,.5,.22);sNz(t+.16,.42,'bandpass',900,2600,1200,.8,.14,.12)}
