var MUSON=(()=>{try{const v=localStorage.getItem('mus');return v==null?1:+v}catch(_){return 1}})(),MUS=null,MSCH=null,KSB={};
function ksBuf(f){const k=Math.round(f);if(KSB[k])return KSB[k];const sr=AC.sampleRate,n=sr*1.3|0,b=AC.createBuffer(1,n,sr),d=b.getChannelData(0),P=Math.max(2,Math.round(sr/f)),ring=new Float32Array(P);
 for(let i=0;i<P;i++)ring[i]=(Math.random()*2-1)*(1-i/P*.3);let idx=0;for(let i=0;i<n;i++){const a=ring[idx],nx=ring[(idx+1)%P];const v=.4985*(a+nx);ring[idx]=v;d[i]=a;idx=(idx+1)%P}
 let pk=0;for(let i=0;i<n;i++)pk=Math.max(pk,Math.abs(d[i]));for(let i=0;i<n;i++)d[i]/=pk||1;return KSB[k]=b}
function pluck(f,t,a,pan){const s=AC.createBufferSource();s.buffer=ksBuf(f);const g=AC.createGain();g.gain.setValueAtTime(a,t);g.gain.exponentialRampToValueAtTime(.0001,t+1.2);const hp=AC.createBiquadFilter();hp.type='highpass';hp.frequency.value=f<200?150:110;let o=g;try{if(AC.createStereoPanner){const p=AC.createStereoPanner();p.pan.value=pan||0;g.connect(p);o=p}}catch(_){}s.connect(hp);hp.connect(g);o.connect(MUS);s.start(t);s.stop(t+1.25)}
const MNF=n=>440*Math.pow(2,(n-69)/12);
// D dorico: progresion Dm - C - Bb - C / Dm - F - C - Dm
const MCH=[[50,57,62,65],[48,55,60,64],[46,53,58,62],[48,55,60,64],[50,57,62,65],[53,57,60,65],[48,55,60,64],[50,57,62,65]];
const MMEL=[[74,72,74,77,76,74,72,69],[72,71,72,76,74,72,71,67],[70,72,74,70,69,67,69,70],[72,74,76,72,71,67,72,74],[74,77,79,77,76,74,76,77],[77,76,74,72,74,77,81,79],[76,74,72,74,76,72,71,67],[69,72,74,72,69,67,69,62]];
function musStart(){if(!AC||MSCH)return;if(!MUS){MUS=AC.createGain();MUS.gain.value=.38;MUS.connect(MG)}let bar=0,next=AC.currentTime+.15;const E=60/104/2;
 MSCH=setInterval(()=>{if(!AC)return;while(next<AC.currentTime+.6){const c=MCH[bar%8],m=MMEL[bar%8],vr=(bar/8|0)%2;
  pluck(MNF(c[0]-12),next,.28,-.2);[0,2].forEach(b=>{c.slice(1).forEach((n,i)=>pluck(MNF(n),next+b*2*E+i*.018,.22,.15))});[1,3].forEach(b=>c.slice(1).forEach((n,i)=>pluck(MNF(n),next+b*2*E+(2-i)*.014,.14,.15)));pluck(MNF(c[0]-5),next+4*E,.2,-.2);
  m.forEach((n,i)=>{if(vr&&i%4==3)return;const nn=vr&&i%2?n+(i%4==1?2:-2):n;pluck(MNF(nn),next+i*E,.32,.05);if(i%2==0&&Math.random()<.25)pluck(MNF(nn+12),next+i*E+E/2,.12,.1)});
  next+=8*E;bar++}},150)}
function musStop(){if(MSCH){clearInterval(MSCH);MSCH=null}}
function musApply(){if(!AC)return;if(MUSON==1){musStart();if(AG)AG.gain.value=0}else{musStop();if(AG)AG.gain.value=MUSON==2?0:1.1}const b=$('musb');if(b)b.textContent=tr(['♪ Música','🔥 Fogata','🔇 Silencio'][MUSON==1?0:MUSON==2?2:1])}
